-- Generated by `npm run campaign:seed` from src/features/journey/content/. Do not
-- edit by hand: change the content, bump its contentVersion and regenerate into a
-- new migration. Nodes are never deleted here — removing one that players already
-- have progress on needs its own reviewed migration.

-- Region "sinnoh", content version 4.
on conflict (id) do update set
  name = excluded.name,
  sort_order = excluded.sort_order,
  content_version = excluded.content_version;

on conflict (id) do update set
  region_id = excluded.region_id,
  sort_order = excluded.sort_order,
  kind = excluded.kind,
  title = excluded.title,
  summary = excluded.summary,
  npc_name = excluded.npc_name,
  encounter_kind = excluded.encounter_kind,
  encounter_difficulty = excluded.encounter_difficulty,
  required_victories = excluded.required_victories,
  repeatable = excluded.repeatable,
  badge_name = excluded.badge_name,
  scene_intro = excluded.scene_intro,
  scene_outro = excluded.scene_outro;

delete from public.campaign_node_prerequisites
  where node_id in (select id from public.campaign_nodes where region_id = 'sinnoh');

delete from public.campaign_node_wild_encounters
  where node_id in (select id from public.campaign_nodes where region_id = 'sinnoh');

